<div class="border-t border-base-300 p-5 flex flex-wrap justify-between items-center gap-3 text-sm"><p><?= $total ?> registros · Página <?= $page ?> de <?= max(1,(int)ceil($total/25)) ?></p><nav aria-label="Paginación" class="flex gap-2"><?php if ($page>1): ?><a class="btn btn-sm" href="<?= site_url($base).'?'.esc(http_build_query($params+['page'=>$page-1]),'attr') ?>">Anterior</a><?php endif ?><?php if ($page*25<$total): ?><a class="btn btn-sm" href="<?= site_url($base).'?'.esc(http_build_query($params+['page'=>$page+1]),'attr') ?>">Siguiente</a><?php endif ?></nav></div>
